        static int MakeInsert(ref AccountModelsLib.operations opp, ref int Excp, ref string msg, ref string Is_Identity, string mysql)
        {
            Excp = 0;
            int C = 0;
            try
            {
                try
                {
                    (string TableName, long Id) = SqlInsertParser.ParseInsertStatement(mysql) ?? (string.Empty, 0);
                    string s = " select Id from " + TableName + " where Id = " + Id;
                    DataTable dt = opp.return_DataTable(s);
                    if (dt.Rows.Count > 0)
                    {
                        return 0;
                    }
                }
                catch (Exception ee)
                {

                }
                if (Is_Identity.Trim() != "")
                {
                    mysql = Is_Identity + " " + mysql;
                }

                C = opp.insert_me(mysql);
                Excp = 0;
            }
            catch (Exception ee)
            {
                Excp = 1;
            }
            return C;
        }

