    public class SqlInsertParser
    {
        // Regex breakdown:
        // INSERT\s+(?:INTO\s+)?(?:\[?\w+\]?\.)?\[?(?<table>\w+)\]? -> Captures table name, handles [dbo].[TableName] or TableName
        // VALUES\s*\(\s*(?:CAST\s*\(\s*)?(?<id>\d+)                 -> Matches the first value after VALUES(, handles CAST(970... or plain 970
        private static readonly Regex InsertRegex = new Regex(
            @"INSERT\s+(?:INTO\s+)?(?:\[?\w+\]?\.)?\[?(?<table>\w+)\]?.*?VALUES\s*\(\s*(?:CAST\s*\(\s*)?(?<id>\d+)",
            RegexOptions.IgnoreCase | RegexOptions.Compiled
        );

        public static (string TableName, long Id)? ParseInsertStatement(string sql)
        {
            if (string.IsNullOrWhiteSpace(sql))
                return null;

            var match = InsertRegex.Match(sql);

            if (match.Success)
            {
                string tableName = match.Groups["table"].Value;
                if (long.TryParse(match.Groups["id"].Value, out long id))
                {
                    return (tableName, id);
                }
            }

            return null;
        }
    }
